#[test]
fn test_cursor_new_and_remaining() {
    let data = &[1u8, 2, 3, 4, 5];
    let c = Cursor::new(data, 2, 1, 2);
    assert_eq!(c.pos, 2);
    assert_eq!(c.remaining(), 3);
}

#[test]
fn test_cursor_u8_u16_u32_u64() {
    let data = &[
        0x01u8, 0x02, 0x00, 0x03, 0x00, 0x00, 0x00, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00,
    ];
    let mut c = Cursor::new(data, 0, 1, 1);
    assert_eq!(c.u8().unwrap(), 1);
    assert_eq!(c.u16().unwrap(), 2);
    assert_eq!(c.u32().unwrap(), 3);
    assert_eq!(c.u64().unwrap(), 4);
    assert_eq!(c.pos, 15);
    assert!(c.u8().is_err());
}

